const v = msg.payload;
msg.payload = (v === 1 || v === "1" || v === true);
return msg;

// Map of key IDs to names
const keyMap = {
    "27184202138": "Blue Chip",
    "11679151219": "White Card",
    "ABCDEF12": "Other"
};

flow.set("booking_key", msg.payload);
flow.set("booking_key_name", keyMap[msg.payload] || msg.payload);

return null;

// Get values
let dtString = flow.get("booking_datetime");
let keyId = flow.get("booking_key");
let keyName = flow.get("booking_key_name");

// Parse datetime string
let dt = new Date(dtString);

// Format for Vienna timezone
let options = {
    timeZone: "Europe/Vienna",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
};
let formatted = new Intl.DateTimeFormat("de-AT", options).format(dt);

// Calculate delay until booking time
let now = new Date();
let delayMs = dt.getTime() - now.getTime();

if (delayMs < 0) {
    node.warn("Booking time is in the past");
    return null;
}

// Message to send after delay
msg.payload = keyId;
msg.delay = delayMs;
msg.display = `${formatted} – ${keyName}`;
return msg;

// raw kann String ("2025-12-13T18:30") ODER Number (1766659380000) sein
let raw = flow.get("partyDateTimeString");

// 1) Wenn Number: direkt als ms-Timestamp verwenden
let bookingTs = null;
if (typeof raw === "number" && Number.isFinite(raw)) {
  bookingTs = raw;
} else {
  // 2) Wenn String: parsen
  if (typeof raw !== "string") raw = "";
  raw = raw.trim().replace(" ", "T");
  const d = new Date(raw);
  const ts = d.getTime();
  bookingTs = Number.isFinite(ts) ? ts : null;
}

if (!bookingTs) {
  msg.payload = "Ungültige oder leere Datum/Zeit-Eingabe.";
  return [msg, null];
}
// toTimestamp: akzeptiert "YYYY-MM-DDTHH:MM" oder "YYYY-MM-DD HH:MM"
function toTimestampLocal(s) {
    if (!s || typeof s !== "string") return null;
    s = s.trim().replace(" ", "T");          // " " -> "T"
    // datetime-local liefert ohne Sekunden; Date kann das lokal parsen.
    const d = new Date(s);
    const ts = d.getTime();
    return Number.isFinite(ts) ? ts : null;
}

// formatLocal: Anzeige in Europe/Vienna
function formatLocalVienna(ts) {
    return new Date(ts).toLocaleString("de-AT", {
        timeZone: "Europe/Vienna",
        year: "numeric", month: "2-digit", day: "2-digit",
        hour: "2-digit", minute: "2-digit"
    });
}

flow.set("partyBookingTs", bookingTs);
flow.set("partyTriggered", false);

const formatted = formatLocalVienna(bookingTs);

// Output 1: fürs Dashboard/Text
const outUi = { payload: formatted };

// Output 2: an MQTT (next-party)
const outMqtt = {
    topic: "resort/house3/party/next",
    payload: formatted
};

return [outUi, outMqtt];

const formatLocal = flow.get('formatLocal');
const bookingTs = flow.get('partyBookingTs');
const triggered = flow.get('partyTriggered') || false;

if (!bookingTs || triggered) return null;

const now = Date.now();
const windowMs = 1 * 60 * 1000; // Toleranzfenster, z.B. 1 Minuten nach Buchungszeit

// Debug, um zu sehen was passiert
node.log("Check booking: now=" + now + " bookingTs=" + bookingTs);

// Liegen wir im Zeitfenster?
if (now >= bookingTs && now <= bookingTs + windowMs) {
    flow.set('partyTriggered', true);

    // Nachricht an Haus 3 -> Party START
    const outMqtt = {
        topic: "resort/house3/party/cmd",
        payload: "START"
    };

    // Status fürs Dashboard
    const outStatus = {
        payload: "Party automatisch gestartet um " + formatLocal(bookingTs)
    };

    return [outMqtt, outStatus];
}

// Noch zu früh oder schon vorbei
return null;
